      "TrafficInfo": "［開車前往］從台北出發（經宜蘭交流道）：台北→國道5號→宜蘭(交流道)→省道台7線→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山。［開車前往］從台北出發（經羅東交流道）：台北→國道5號→羅東(交流道)→省道台7丙線→省道台7線→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山。［開車前往］從台北出發（經省道台9線(北宜公路)）：台北→省道台9線(北宜公路)→頭城鎮→宜蘭市→省道台7線→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山［開車前往］從基隆出發：基隆→省道台2線(濱海公路) →壯圍→省道台7線→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山。［開車前往］從桃園出發：桃園→大溪→省道台7線(北橫公路)→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山。［開車前往］從花蓮出發：花蓮→省道台9線(蘇花公路)→省道台7丙線→省道台7線→省道台7甲線(3.7K)→宜專1線→土場→鳩之澤→太平山。［大眾運輸］搭乘國光客運：每日行駛(平日:1750 假日:1750A)。旅程時間：約2時30分鐘。電話：宜蘭站03-9384171、羅東站03-9567505。網址：http://www.kingbus.com.tw。購票方式：國光客運臨櫃購票、網路購票及三大超商(7-11、全家及萊爾富)購票。預定當日起15天內車票(含回程訂位) ◎去程(發車時間)：宜蘭07:40、羅東08:00(宜蘭+20分鐘為羅東發車時間) ；抵達太平山10:30。 ◎回程(發車時間)：太平山14:30；鳩之澤16:10，抵達羅東17:30、宜蘭17:50。［大眾運輸］搭乘觀光局台灣觀光巴士：搭乘觀光局台灣觀巴-宜蘭太平山自然之旅一日遊，四人即可成行（提供英、日外語導覽） https://www.taiwantourbus.com.tw/C/tour/tw/yilan-taipingshan-nature-tour［大眾運輸］參加太平山策略聯盟夥伴套裝行程：太平山國家森林遊樂區生態旅遊策略聯盟夥伴，有4家旅行社夥伴，可提供接駁及套裝行程。說明網址：http://goo.gl/BP1YdE",
