      "TrafficInfo": "［開車前往］路線一：國道3號→三鶯交流道→縣道110線→三峽→省道台3線→大埔→左岔路往省道台7乙線→湊合→插角→有木里方向→樂樂谷→滿月圓國家森林遊樂區(共4個停車場，第1號為小型停車場38格、第2號為大小型車停車場(具807公車候車亭)，大型停車格10格，小型停車格29格，第3號為小型車兩層停車場，上層為28個格、下層為20格，第4號為小型車及機車停車場，16格小型停車格)。［大眾運輸］搭乘客運：自三峽搭乘臺北客運【807】三峽--滿月圓: 平日『三峽一站發車時間』05:20、07:00、09:30、12:00、15:00、17:30。        『滿月圓發車時間』06:05、07:45、10:15、12:45、15:45、18:10。例假日『三峽一站發車時間』06:00、08:30、11:00、14:30、17:30。            『滿月圓發車時間』06:45、09:10、11:45、15:15、18:10。臺北客運三峽一站電話02-26711914，往滿月圓第2停車場，下車沿蚋仔溪生態步道步行約30分鐘即可到達售票站。",
