      "TrafficInfo": "國道3號→新店交流道→省道台9線→新店→烏來→信賢區→內洞。［大眾運輸］搭乘計程車(烏來台車-內洞國家森林遊樂區)(車程約16分鐘)：建議可於「烏來轉運站」或「烏來台車站入口處」前方之「計程車處」搭乘計程車至內洞國家森林遊樂區1.從「烏來轉運站」搭乘計程車至內洞國家森林遊樂區搭乘費用425元2.從「烏來台車站入口處(纜車站)」至內洞國家森林遊樂區搭乘費用285元◎大臺北地區計程車新運價依新北市政府公告為主 (連結網址https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=6de3731612ab144a8911537a2a34e600#)［大眾運輸］搭客運再步行或搭乘計程車至內洞國家森林遊樂區：搭乘新店客運849公車可於「烏來轉運站」下車，步行約6.8公里約1小時30分抵達內洞園區。",
      "ParkingInfo": "小型車：免收費，停車場收費時間:平日自上午7時至下午6時，假日自上午6時至下午6時。第1小時收費新台幣30元，第2小時起收費新台幣20元，當日最高新台幣100元。",
