      "TrafficInfo": "［開車前往］路線一：桃園→大溪→省道台7線→復興→縣道119線→東眼山森林遊樂區。［開車前往］路線二：三峽→大埔→省道台7乙線→三民→省道台7線復興→縣道119線→東眼山森林遊樂區。［大眾運輸］台灣好行【506】東眼山線：台灣好行【506】東眼山線:『大溪發車時間』(平日)08:00、11:00、15:00/(假日)08:00、09:00、11:00、14:30、15:00。『東眼山國家森林遊樂區發車時間』(平日)09:30、13:00、17:00/(假日)09:30、12:00、13:00、16:15、17:00(下車處在東眼山售票口外，上車處在東眼山內大型停車場處)其他乘車資訊可洽*桃園客運 (0800-053808)*台灣好行 (0800-011765) *台灣好行網頁連結: https://www.taiwantrip.com.tw/Frontend/Route/Select_p?RouteID=R0064*東眼山遊樂區 (03-3821506)［大眾運輸］幸福巴士[F906蝙蝠洞-東眼山路線]：三民→水流東(越香飲食店)→水流東路口→大窩路口→土地公→張厝→三叉路口→三民長老教會→蝙蝠洞口→紅瓦厝→吳厝→西湖→王厝→大窩→下基國派→基國派→三民停車場→枕頭山口→圓山腳→圓山→圓山橋→枕頭山→檀林寺→三民橋→新村→水源地→介壽國中→角板山公園→復興→角板山公園→介壽國中→水源地→成福路口→綠光森林→東眼山國家森林遊樂區",
      "ParkingInfo": "大型車：100元，1.大型停車格為22格車位。2.搭乘公車及客運離園乘車處。小型車：100元，小型停車場一區為104格車位，另一區為116格車位，共220格車位。機車：20元，機車停車場(現有30格，位於小型停車場左側)。",
