      "TrafficInfo": "［開車前往］路線一：國道3號竹林交流道→縣道120線→竹東→縣道122線(南清公路)→清泉→大鹿林道→觀霧 (自竹東至觀霧車程約需2小時)。［開車前往］路線二：新竹→快速道路68號→竹東-縣道122線(南清公路)→清泉→大鹿林道→觀霧 (自竹東至觀霧車程約需2小時)。［大眾運輸］台灣好行-觀霧縣：「台灣好行-觀霧線」共停靠高鐵新竹站、台鐵竹東站、軟橋彩繪村、五峰清泉、雲山民宿、雪霸休閒農場、觀霧國家森林遊樂區及觀霧山莊等8站，單程票價新臺幣300元，建議電話預約搭乘，電話專線：037-597688，0911-363360。服務時間：週一至週五上午08:00-12:00、下午13:30-17:30。",
