      "TrafficInfo": "［開車前往］路線一：桃園→大溪→省道台7線→復興→縣道116線→拉拉山森林遊樂區。［開車前往］路線二：羅東→省道台7線→明池→縣道116線→拉拉山森林遊樂區。［大眾運輸］搭乘客運：本區目前有桃園客運5090、5091路線及中壢客運5301路線提供載客服務，3條路線營運起點分別為桃園、中壢站，其迄點均為桃園市復興區桃116線終點林班口［大眾運輸］付費接駁車：若需搭乘付費接駁車，可洽詢與本分署簽署合作備忘錄之拉拉山車隊，窗口電話0989-021005、0981-130771。",
      "ParkingInfo": "小型車：100元，小型車每輛新臺幣100元請將車輛停放在停車格拉拉山園區內路幅較窄，所以不開放甲、乙類客車、保母車 ，進入的車輛車長限6公尺、車寬限2公尺。機車：20元，機車每輛新臺幣20元請將機車停放在機車停車格。",
