      "Description": "深藏在武陵農場深處，楓紅、松林、瀑布與臺灣櫻花鉤吻鮭譜出的森林之歌，是武陵國家森林遊樂區最令人印象深刻的意象。  這是台灣第三座國家森林遊樂區，距離台北約4個小時車程，海拔約1800公尺，但因高山寒氣沈降，十分寒冷。  園區內最具代表性的景點，莫過於桃山瀑布步道，沿途的二葉松林相十分幽靜，豐富的森林生態也是這裡的一大特色，台灣獼猴、帝雉、藍腹鷴、酒紅朱雀都是這裡的常客，步道盡頭水與霧雄壯澎湃的「桃山瀑布」令人歎為觀止，釋放滿滿的負離子療癒旅人的心靈。  在武陵吊橋上，還可以觀賞七家灣溪裡的國寶魚——臺灣櫻花鉤吻鮭呢！秋天的台灣紅榨槭、青楓紅葉，與春天的櫻花更是武陵國家森林遊樂區美麗的季節特色，是來到武陵一帶不可錯過的行程喔！  武陵國家森林遊樂區內台灣獼猴出沒頻繁，為減少人猴衝突，請遵守4不守則：  1.不餵食 ■餵食會降低獼猴對人的警戒心，使獼猴進而搶食人類食物，危及人身安全。 ■餵食會改變獼猴自然行為與生態，使獼猴與人類生活易產生衝突。 2.不接觸 ■不接觸獼猴，避免感染泡疹B病毒、狂犬病、腸胃道寄生蟲等人猴共通疾病。 ■獼猴跳到身上時，勿驚慌尖叫揮趕，鎮定離開原地，獼猴會自己離開。 3.不干擾挑釁 ■不瞪視、不逗弄、不挑釁、不讓孩童落單，減少人猴衝突。 4.食物不外露 ■零食、水果、飲品或任何具濃郁氣味的食品，應收入背包內不提拿在手上，也不要在獼猴面前作拉開背包的動作，減少獼猴上前拿取之衝突。",
