      "TrafficInfo": "［開車前往］台北→宜蘭→棲蘭→南山→武陵國家森林遊樂區。［開車前往］桃園→三民→巴陵→明池→棲蘭→南山→武陵國家森林遊樂區。［開車前往］王田交流道→草屯→埔里→霧社→合歡山→梨山→武陵國家森林遊樂區。［開車前往］台中→中投快速道路→埔里→省道台8線→霧社→合歡山→梨山→省道台7甲線→武陵國家森林遊樂區。［開車前往］花蓮→太魯閣→省道台8線(中橫公路→大禹嶺→梨山→省道台7甲線→武陵國家森林遊樂區。［開車前往］台北→國道3號→國道5號→頭城→省道台9線→省道7線→棲蘭→省道台7甲線→武陵國家森林遊樂區。［開車前往］東勢→台八線→中橫→梨山→武陵國家森林遊樂區：管制路段(https://www.thb.gov.tw/News_Content_table.aspx?n=87&s=41033)［大眾運輸］搭乘客運-台中谷關出發：自谷關搭乘往梨山之豐原客運865路於梨山站下車，再轉搭豐原客運866區2於武陵農場站下車。台中豐原客運相關連結:http://www.fybus.com.tw/，(04)25234175。［大眾運輸］搭乘客運-羅東轉運站出發：搭乘台鐵至羅東站，步行至羅東轉運站，搭乘國光客運1764號，至武陵農場下車。國光客運相關連結：http://www.kingbus.com.tw，免付費服務電話0800-010-138。［大眾運輸］搭乘客運-宜蘭轉運站出發：搭乘台鐵至宜蘭站，步行至宜蘭轉運站，搭乘國光客運1751號，至武陵農場下車。國光客運相關連結：http://www.kingbus.com.tw，免付費服務電話0800-010-138。［大眾運輸］武陵國民賓館至武陵山莊接駁服務：需四人以上成行，單趟100元/人。武陵農場預約電話(04)25901259 #9。",
