      "AttractionID": "Attraction_345040000G_000008",
      "AttractionName": "八仙山國家森林遊樂區",
      "AlternateNames": [],
      "Description": "「八仙山為昔日三大林場之一，走過繁華喧囂的林業時光，於民國75年(1986)成立八仙山國家森林遊樂區，如今園區運用其資源地位，轉化林場設施語彙，復刻過去歷史記憶，並規劃具有景色多樣化的輕裝短途步道，園區內能尋訪美麗的十文溪、櫻花林、油桐林與竹林，更能循階登頂谷關七雄之首：海拔2366公尺的八仙山。 「八仙山」的命名是由日文轉譯而來，因為八仙山有「八千」日尺高，而取其諧音名為「八仙」。自1915年起至1963年間，八仙山長達48年的林業時光，留下了整齊劃一的人造林、索道頭以及神社和國小遺址等，訴說著林業的故事。而曾有過的森林鐵道，也在結束伐木後全數拆除，僅剩園區內的老照片供人回憶；除了史蹟尋訪外，園區內有非常豐富的鳥類生態，青背山雀、赤腹山雀、白耳畫眉及冠羽畫眉等都是常見的小明星，近年還觀察到國內首筆百步蛇野外護卵的紀錄，此外夜晚還有機會看到大赤鼯鼠、白面鼯鼠、鼬獾及食蟹獴等野生動物，臺灣獼猴則是日間最常在園區走跳的大明星。」",
