      "TrafficInfo": "［開車前往］國4(豐勢交流道下)→臺3線→東勢→臺8線(往谷關)→篤銘橋右轉→八仙山：國道4號(豐勢交流道下)→臺3線左轉，往東勢方向→經東勢大橋右轉進入臺8線、往谷關→經和平→臺8線33K至篤銘橋右轉→至八仙山國家森林遊樂區。［開車前往］甲類客車注意路段：八仙山林道甲類客車行駛應特別注意事項路段：0K+150、1K+051、2K+500、2K+800、3K+000、3K+100、3K+200、3K+500及 3K+900等9處。［大眾運輸］搭乘客運-台鐵豐原站出發：由台鐵豐原西側出口(中正路)，步行約五分鐘搭乘豐原客運207號公車至谷關總站下車，再由總站轉搭269號公車至八仙山遊樂區。台中豐原客運相關連結:http://www.fybus.com.tw/bus8.htm，(04)25234175。［大眾運輸］搭乘客運-高鐵台中站出發：由高鐵6號出口，公車第21號月台，搭乘豐原客運153號公車至谷關總站下車，再由總站轉搭269號公車至八仙山遊樂區，亦可搭臺中市公車「153延」(每日1班)至八仙山森林遊樂區站下。台中豐原客運相關連結:http://www.fybus.com.tw/bus8.htm，(04)25234175。［大眾運輸］搭乘客運-台鐵台中站出發：由台鐵東站出口，搭乘豐原客運850號公車至谷關總站下車，再由總站轉搭269號公車至八仙山遊樂區。台中豐原客運相關連結:http://www.fybus.com.tw/bus8.htm，(04)25234175。",
      "ParkingInfo": "大型車：100元，第三停車場。小型車：100元，第一停車場。小型車：100元，第二停車場。機車：20元，第一停車場。機車：100元，重型機車比照小型汽車收停車費。機車：100元，重型機車比照小型汽車收停車費。",
