      "TrafficInfo": "［開車前往］：國道4號(豐勢交流道下)→臺3線左轉，往東勢方向→經東勢大橋右轉進入臺8線→東關路直走約2公里紅綠燈處左轉(轉彎處右邊為全家便利商店、左前方為雙崎工作站)→往東坑路(大雪山林道)直走→約一小時又三十分可至大雪山國家森林遊樂區。［開車前往］大雪山林道15K+100以上全線禁行甲類大客車：※大雪山林道乙類客車行駛應特別注意路段：5K+200、6K+700、13K+400、15K+300、20K+800、24K+500、26K+500、28K+250、35K+900、36K+800、39K+850、44K+600、47K+500等13處。［大眾運輸］搭乘客運-台鐵豐原站出發：一、由豐原轉運中心搭乘台灣好行889大雪山線，每日4班次至大雪山森林遊樂區，去程最早上午7:15發車，回程最晚下午4:45，搭乘須先洽中台灣客運以電話預約座位，電話：0800676676轉2，台灣好行大雪山線詳細資訊：(https://www.taiwantrip.com.tw/)  二、由豐原轉運中心搭乘豐原客運90、206、207號公車 至東勢站下車轉搭252號(僅六、日行駛)公車至大雪山遊樂區。台中豐原客運相關連結:http://www.fybus.com.tw/bus8.htm前往查詢，(04)25234175。［大眾運輸］搭乘客運-高鐵台中站出發：由高鐵6號出口，公車第21號月台，搭乘豐原客運153號公車 至東勢站下車，再轉搭252號(僅六、日行駛)公車至大雪山遊樂區。台中豐原客運相關連結:http://www.fybus.com.tw/bus8.htm前往查詢，或洽(04)25234175。",
      "ParkingInfo": "大型車：100元。小型車：100元。機車：20元。機車：100元，重型機車比照小型汽車收停車費。",
