      "TrafficInfo": "［開車前往］國6→末端埔里交流道→台14線→霧社→台14甲線→合歡山。：國道6號末端埔里交流道下，沿省道台14線到霧社後轉台14甲線至合歡山。［開車前往］花蓮太魯閣→台8線→大禹嶺→臺14甲線→合歡山：由花蓮太魯閣走省道台8線至大禹嶺轉省道台14甲線至合歡山。(省道台14甲線為中部通往花蓮要道，假日容易塞車)［大眾運輸］搭乘客運說明：先至埔里再至清境農場，可搭乘南投客運6658、6659、6664路線至清境農場再轉乘清境-武嶺-合歡山路線(6658A)至松雪樓。南投客運客服電話(049)2984-031。［大眾運輸］幸福巴士及幸福小黃營運資訊：【固定路線(6658A)】公車接駁處→國民賓館→清境農場旅服中心→觀山牧區→青青草原→娜嚕灣→蘋果園→富嘉果園→仁莊→挪威森林→松崗→梅峰→道班房→翠峰→鳶峰→武嶺→松雪樓→石門山→合歡山管理站→小風口【彈性路線】埔里→霧社→清境農場→合歡山→奧萬大→廬山溫泉→廬山→松崗→翠峰→萬大→國姓→魚池南投客運電話：049-2984031網址：http://www.ntbus.com.tw/cj-m.html網路預約：http://www.ntbus.com.tw/bs-go.html",
      "ParkingInfo": "小型車：25元，週一～週四(不含例假日及國定假日)汽車(每半小時)25元。重機「250cc以上」(每半小時)25元，當日最高上限300元。停車有15分鐘內免費之緩衝措施，停車場採取柵欄式管控進出，汽車以車牌辨識，於自動繳費機繳費後離場。汽車採用AI動態影像辨識進出場。重機採用後車牌辨識入場，無需掃描QR Code，但需停放於指定辨識區域內，但請避免因置物箱影響辨識。因應大雪濃霧時，汽車、重機皆維持正常辨識與繳費流程，如遇極端惡劣天候則另行公告處理。付款方式各停車場如下：合歡山山莊、武嶺、大昆陽：悠遊卡、一卡通、現金、多元支付(Linepay、街口支付、台灣PAY、悠遊付、拍錢包、全支付、全盈PAY)，及線上信用卡支付繳費。小昆陽：悠遊卡、一卡通與大昆陽通用繳費機功能互相可使用。現金僅接受幣別為：10元、50元、100元。機車：20元，排氣量c.c.≦250之機車，每次20元。昆陽停車場，機車以投幣20元(10元兩枚)入場，離場無須再次繳費武嶺停車場，機車可直接入場，離場時可使用悠遊卡、一卡通或投幣20元(10元兩枚)。現金僅接受幣別為：10元、50元、100元。小型車：30元，週五～週日(含例假日)及國定假日，汽車(每半小時)30元。重機「250cc以上」(每半小時)30元，當日最高上限300元。停車有15分鐘內免費之緩衝措施，停車場採取柵欄式管控進出，汽車以車牌辨識，於自動繳費機繳費後離場。汽車採用AI動態影像辨識進出場。重機採用後車牌辨識入場，無需掃描QR Code，但需停放於指定辨識區域內，但請避免因置物箱影響辨識。因應大雪濃霧時，汽車、重機皆維持正常辨識與繳費流程，如遇極端惡劣天候則另行公告處理。付款方式各停車場如下：合歡山山莊、武嶺、大昆陽：悠遊卡、一卡通、現金、多元支付(Linepay、街口支付、台灣PAY、悠遊付、拍錢包、全支付、全盈PAY)，及線上信用卡支付繳費。小昆陽：悠遊卡、一卡通與大昆陽通用繳費機功能互相可使用。現金僅接受幣別為：10元、50元、100元。",
