      "TrafficInfo": "［開車前往］路線一：國道3號霧峰系統交流道(214k)→國6號埔里端→左轉霧社方向→右轉投83線→奧萬大國家森林遊樂區。［開車前往］路線二：北部南下→國道一號→彰化系統交流道(193K)→國道三號→霧峰系統交流道(214K)→國道6號埔里端→左轉台14→霧社→ 右轉投83線→奧萬大。［開車前往］路線三：南部北上→國道1號→經東西向快速道路(例如台78、82、84)→國道3號→霧峰系統交流道(214k)國道6號埔里端→左轉霧社方向→右轉投83→奧萬大國家森林遊樂區。［開車前往］路線四：花蓮出發→省道台8線→大禹嶺→省道台14甲線→霧社→奧萬大國家森林遊樂區。［大眾運輸］南投客運奧萬大賞楓專車(目前停駛)：於賞楓旺季期間（10月至隔年3月底）之星期六日，由南投客運干城站發車採預約訂位（站牌與時刻表資訊:http://www.ntbus.com.tw/bs-tour.html）。訂位專線：049-2984031分機23 林小姐。台中干城站：台中市雙十路一段35-8號。高鐵台中站：高鐵站區一樓五號出口。［大眾運輸］幸福巴士及幸福小黃營運資訊(請洽南投客運確認是否行駛)：【彈性路線】埔里→霧社→清境農場→合歡山→奧萬大→廬山溫泉→廬山→松崗→翠峰→萬大→國姓→魚池南投客運電話：049-2984031網址：http://www.ntbus.com.tw/cj-m.html網路預約：http://www.ntbus.com.tw/bs-go.html",
