      "TrafficInfo": "［開車前往］路線一：由國道3號(南二高)中埔交流道下後接臺18線省道（阿里山公路）至阿里山國家森林遊樂區(88.2K處)。［開車前往］路線二：由國道1號(中山高)嘉義交流道下後接臺18線省道（阿里山公路）至阿里山國家森林遊樂區(88.2K處)。［開車前往］肢體障礙遊客車輛自駕入園申請：為方便肢體障礙需倚靠輪椅之行動不便遊客遊園，「肢體障礙需倚靠輪椅始可行動，且領有身心障礙手冊或證明之本人及陪伴者1人」可以預約申請自駕通行區內第一、二管制哨，車種需非屬甲、乙類大客車之復康巴士、無障礙計程車或福祉車(自有廂型車加裝電動升降機或斜坡道者)。開放預約之時段、限額、申請方式請詳連結 http://chiayi.forest.gov.tw/0000352。［開車前往］公路路況資訊：公路路況1. 幸福公路 https://apps.apple.com/tw/app/%E5%B9%B8%E7%A6%8F%E5%85%AC%E8%B7%AF/id6046983602.智慧化省道即時資訊https://168.thb.gov.tw/thb1683. 雲嘉南區養護工程分局 https://thbu5.thb.gov.tw/News.aspx?n=5264&sms=13367 ［開車前往］入園車輛限制：1.車輛可到達園區內大型車停車場(僅供臨停):乙類中巴、甲類大巴。2.車輛可到達園區內旅舍區及遊客服務中心前停車場:小客車。［大眾運輸］搭乘嘉義縣公車：嘉義縣公車﹝嘉義-阿里山﹞、台灣好行【7329嘉義高鐵-阿里山】【7322嘉義台鐵-阿里山】於阿里山入口轉運站下車。車班及行駛狀況請洽：嘉義縣公車處：(05)278-8177網址資訊如下：嘉義縣公車 | 阿里山線：https://bus.cyhg.gov.tw/News_Content.aspx?n=4441&s=55223。台灣好行 | 阿里山線：https://www.taiwantrip.com.tw/Frontend/Route/Select_p?RouteID=R0008。台灣好行 | 6739日月潭-阿里山：https://www.taiwantrip.com.tw/Frontend/Route/Select_p?RouteID=R0099。［大眾運輸］搭乘員林客運：員林客運﹝阿里山-日月潭﹞於阿里山入口轉運站搭乘，請提前預約劃位，行駛狀況請洽員林客運水里站：049-2770041。網址資訊如下：https://www.taiwanbus.tw/eBUSPage/Query/QueryResult.aspx?rno=67390&rn=1609311024328&fbclid=IwAR0Lmx0zwQxF0dnEhHWc-GHdHaVLg9geIwBDq5FPKeRwPZ-8ZOjxfzuZTMI&lan=C［大眾運輸］搭乘國光客運：國光客運﹝1835臺北-阿里山﹞，車班及行駛狀況，請洽：國光客運0800-010-138或臺北轉運站，電話：(02)7733-5888。國光客運 | 1835臺北-阿里山https://www.taiwanbus.tw/eBUSPage/Query/QueryResult.aspx?rno=18350&lan=C［大眾運輸］區內電動遊園車：遊樂區內共有10輛經ARTC安檢合格並合法掛牌之電動中巴，營業時間為每日8-17時，於區內4處遊園車站：【候車總站】、【沼平站】、【旅客服務中心站】、【香林服務區站】、【水山療癒步道站】來回接駁。每日【旅客服務中心站/沼平站-祝山站】發車時間：9時、11時、13時、15時；返程【祝山站-旅客服務中心站/沼平站】發車時間：9：30、11：30、13：30、15：30、16：30。另有【祝山觀星線】每日19時發車（需預約並視天候狀況調整）及【祝山日出線】。客服專線：0800-263-520 或 「阿里山遊園車」FB 留言洽詢https://www.facebook.com/alishanebus/。［大眾運輸］搭乘阿里山小火車：阿里山火車本線：嘉義車站到阿里山車站的鐵路。阿里山小火車支線：阿里山森林園區內的祝山線、沼平線、神木線。訂票方式及時刻表，請至阿里山林業鐵路網路訂票系統 https://afrts.forest.gov.tw/TP01_1.aspx 查詢或電洽北門站「05-2768094」、 阿里山站「05-2679200」詢問。［大眾運輸］「搭乘高鐵」轉乘：可轉乘台灣好行或阿里山郵輪式巴士上山，購票網址：https://reurl.cc/aMY244",
      "ParkingInfo": "小型車：100元，包含大型重型機車。機車：20元。",
