      "AttractionID": "Attraction_345040000G_000013",
      "AttractionName": "藤枝國家森林遊樂區",
      "AlternateNames": [],
      "Description": "有「森濤」美名的藤枝國家森林遊樂區，是南部地區享受森林浴、夏日避暑、玩賞生態最好的去處。 距離高雄市、屏東市、臺南市約莫2小時車程的藤枝，過去是布農族人的生活區域，日治時期在此設立京都大學實驗林，因此有台灣少見的日本扁柏以及大面積的柳杉造林地。而著名的六龜警備線通過此地，留有不少遺跡。  園區海拔在1500~1804公尺間，涼爽宜人。此地的「霧林帶」中，生長著牛樟、木荷、杏葉石櫟等大樹，更有以此為名的「藤枝秋海棠」與眾多稀有蕨類，十分珍貴；並且孕育了豐富的生態，能找到許多難得一見的昆蟲，如路易士角葫蘆鍬形蟲、大綠目天蠶蛾、台灣爺蟬等。這裡也是全台灣最容易看見黃山雀的地點之一，十分特別，是個十分適合健行賞鳥的好地方呢！",
