      "TrafficInfo": "［開車前往］西部路線：國道3號『林邊交流道』下左轉→省道台17線→枋寮→楓港→省道台26線→墾丁→經過墾丁夏都沙灘酒店→左手邊即可看到墾丁牌樓→行駛公園路約4公里(山路)，經華泰瑞苑後繼續行駛，循指標即可到達園區停車場。［開車前往］西部路線：國道3號『南州交流道』下左轉→省道台1線右轉→枋寮→楓港→省道台26線→墾丁→經過墾丁夏都沙灘酒店→左手邊即可看到墾丁牌樓→行駛公園路約4公里(山路)，經華泰瑞苑後繼續行駛，循指標即可到達園區停車場。［開車前往］東部路線：台東→省道台9線→太麻里→大武→經雙流國家森林遊樂區→楓港→省道台26線南下→墾丁→經過墾丁夏都沙灘酒店→左手邊即可看到墾丁牌樓→行駛公園路約4公里(山路)，經華泰瑞苑後繼續行駛，循指標即可到達園區停車場。［大眾運輸］搭乘客運：1.從高鐵左營站：搭乘國光客運【9188】，或搭台灣好行墾丁快線(9189線) 至墾丁牌樓站下 車，轉乘屏東客運8248線至墾丁公園站下車。2.從高雄火車站:搭乘高雄客運【9117】或【9118】線，至墾丁牌樓站下車，轉乘屏東客運8248線至墾丁公園站下車，即可到達園區。高雄客運服務電話：(07)3457405、(07)3504217［大眾運輸］搭乘客運：1.從屏東火車站：搭乘屏東客運【8239】恆春線至恆春轉運站，直接轉乘屏東客運8248線至墾丁公園站下車，即可到達園區。查詢電話：屏東客運(08)723-7131。2.於恆春轉運站搭乘8248線至墾丁公園站下車。【屏東客運恆春站08-8891464．高墾線共營中心 0800-777767】詳細搭乘路線可參考屏東客運網站https://www.ptbus.com.tw/product_list/0/1?type=1［大眾運輸］屏東縣小黃公車720社頂線營運資訊：路線:恆春鎮公所-恆春鎮衛生所-恆春轉運站-恆春基督教醫院-恆春郵局-恆春農會-南門醫院-恆春旅遊醫院-馬鞍山-墾丁牌樓-墾丁公園-墾丁國家森林遊樂區-社頂社區-社頂公園管理站-恆春水蛙窟社區-坑內-埔頂籠埔宮.詳細搭乘路線資訊可見https://www.pthg.gov.tw/traffic/cp.aspx?n=AA9C05CBD0D1BFB6&s=48F00EC966F4DA0D",
