      "TrafficInfo": "［開車前往］路線一：國號3號南州交流道下→省道台17線→枋寮→楓港→省道台9線→全家便利商店前右轉，即可進入雙流國家森林遊樂區。［開車前往］路線二：台東→省道台9線→知本→太麻里→太武→過全家便利商店後左轉，即可進入雙流國家森林遊樂區。［大眾運輸］搭乘客運：高屏—獅子鄉（往返）：高雄/屏東搭乘台鐵至枋寮火車站，並於枋寮火車站搭乘獅子鄉幸福巴士(需預約0800-00-1129分機16)，在雙流國家森林遊樂區【售票處】下車。幸福巴士路線若有更動，請撥打查詢電話：獅子鄉公所幸福巴士：0800-00-1129分機16或43，將由專人為您服務。",
