      "TrafficInfo": "［開車前往］路線一：省道台9線或台11線→知本→龍泉路(194縣道)→循知本國家森林遊樂區指標即可到達(位於道路終點)。［開車前往］租車前往：搭乘台鐵(http://twtraffic.tra.gov.tw/twrail/TW_Quicksearch.aspx)南迴線至知本火車站下車，再租騎摩托車往知本溫泉方向至知本國家森林遊樂區(騎機車約15分鐘)。［大眾運輸］搭乘客運─東台灣客運：1、台東市或知本火車站搭乘東台灣客運（山線http://ett333023.com.tw/page3_14.htm）8129車次至內溫泉站下車，往知本國家森林遊樂區方向步行約300公尺即可抵達（平日、假日：單程15班次（來回30班次））。東台灣客運查詢電話：089-328269。2、『遇見溫森好』一日遊票券、路線地圖、時刻表及優惠商家資訊： http://ett333023.com.tw/i-chihpen/index.html［大眾運輸］飛機：（1）從台北松山機場搭機至台東豐年機場。（2）搭東台灣客運接駁車到台東轉運站。（3）再搭台東往知本森林遊樂區8129路公車（每日單程15班、來回30班）。［大眾運輸］火車：台北->台東高雄->台東，搭至知本/台東火車站。再轉搭東台灣客運8129路公車/計程車/租車前往。［大眾運輸］YouBike微笑單車：1. 知本火車站 (車站前) - 騎乘 約40分鐘 (8.7km) -  知本國家森林遊樂區 (停車場內)(可租賃 一般 或 電輔車 車型)。2. 園區停車場共有24格車位，詳細站點資訊及車輛/空位即時資訊，請洽 youBike官網 或 app。",
