      "TrafficInfo": "［開車前往］路線一：花蓮市(省道台9線)→壽豐→光復→(台九線245.5K處右轉進入)富源村→循指標可抵，行程約60公里。［開車前往］路線二：台東市(省道台9線)→關山→池上→玉里→瑞穗→(台9線249K處左轉進入)富源村→循指標可抵，車行約114公里。［大眾運輸］搭乘客運：搭花蓮客運：花蓮往瑞穗、玉里班車，於5點10分開始，平均每一個小時1班車，至富源站下車，步行約3公里抵達。花蓮客運：03-8338146。交通部公路總局-公路客運即時動態資訊網https://www.taiwanbus.tw/eBUSPage/Query/RouteQuery.aspx［大眾運輸］飛機轉客運：由花蓮機場轉搭花蓮客運至富源站，步行約3公里抵達。［大眾運輸］搭乘火車：選擇台鐵東部幹線，於富源火車站下車後，步行約3公里或搭計程車抵達。［大眾運輸］搭乘接駁(僅提供住宿遊客)：「天成逸旅－蝴蝶谷」提供瑞穗或車站之定時定點接駁服務，請電洽03-8812379。(僅提供住宿遊客)",
      "ParkingInfo": "大型車：免收費。小型車：100元。機車：50元。",
