      "TrafficInfo": "［開車前往］路線一：台北往花蓮方向：花蓮（省道台九線）→ 吉安→ 南華（往省道台9丙線） → 干城 → 文蘭 →（省道台9丙17公里處往林園路）池南，行程18公里。［開車前往］路線二：台東往花蓮方向：光復（省道台9線）→ 鳳林 → 壽豐（省道台9丙線）→（省道台9丙17公里處往林園路）池南。［大眾運輸］搭乘統聯客運1139：花蓮火車站轉乘統聯客運1139車次往壽豐（經鯉魚潭）方向至「池南站」下車，路旁可見「池南國家森林遊樂區」指示牌，循指標進入步行約900公尺即可抵達池南國家森林遊樂區（池南自然教育中心）。統聯客運聯絡電話0800-676-676。交通部公路總局-公路客運即時動態資訊網https://www.taiwanbus.tw/eBUSPage/Query/RouteQuery.aspx［大眾運輸］搭乘太魯閣客運(台灣好行)303：花蓮站-旅遊服務中心(花蓮前站右手邊)，可於車上購買搭車票劵，搭乘303車次往壽豐（經鯉魚潭）方向至「鯉魚潭潭南遊憩區」站(鯉魚潭)下車，路旁可見「池南國家森林遊樂區」指示牌，循指標進入步行約600公尺即可抵達池南國家森林遊樂區（池南自然教育中心）。臺灣好行客運公司聯絡電話0800-827-656。",
