      "AttractionID": "Attraction_345040000G_020020",
      "AttractionName": "鰲鼓濕地森林園區",
      "AlternateNames": [],
      "Description": "鰲鼓濕地森林園區早期為台灣糖業公司填海造陸從事農、漁、牧事業及種植甘蔗的大本營，但由於地層嚴重下陷、海水入侵地下水層，農場逐漸沒落荒廢。地勢低窪加上周邊海堤圍繞，大雨過後，魚塭及舊有農地形成天然的蓄水池，久而久之，這些水塘濕地之棲地，越來越多候鳥與留鳥棲身及停留於此，成為現今之鰲鼓濕地森林園區。  大面積的造林地十年或是二十年後將茁壯成林，鰲鼓濕地將會成為具有多樣林相及豐富濕地生態資源之國際級生態環境。鰲鼓濕地森林園區以「濕地保育」與「環境教育」做為園區主要發展定位，使鰲鼓濕地森林園區成為生態旅遊及教學研究的基地。",
