      "TrafficInfo": "［開車前往］國道路線一：國道1號272K嘉義系統接東西向快速道路東石-嘉義線(台82線)，朝西往「東石」方向，接平面道路經過東石大橋右轉台17線，於台17線113.5~114k處，左轉經過台61線涵洞向西直行，即可到達園區服務中心「鰲鼓濕地生態展示館」。［開車前往］國道路線二：國道1號272K嘉義系統接東西向快速道路東石-嘉義線(台82線)，朝西往「東石」方向，接平面道路後右轉157縣道，直行接嘉7鄉道，陸續經過港口大橋、聖母橋、港口宮以及台61線涵洞，即可到達園區服務中心「鰲鼓濕地生態展示館」。 ［開車前往］國道路線三：國道1號272K嘉義系統接東西向快速道路東石-嘉義線(台82線)，朝西往「東石」方向，下朴子交流道(台82線10K)右轉文化南路(台19線)，接著左轉四維路二段後，於海通路(168縣道)左轉，直行至嘉7鄉道右轉，陸續經過港口大橋、聖母橋、港口宮以及台61線涵洞，即可到達園區服務中心「鰲鼓濕地生態展示館」。［開車前往］國道路線四：國道3號則由300K水上系統接東西向快速道路東石-嘉義線(台82線)，朝西往「東石」方向，經國道1號272K嘉義系統後參考上述路線，亦可到達園區服務中心「鰲鼓濕地生態展示館」。［開車前往］西濱快速道路(台61線)（南下）：往嘉義於253K處之水井交流道出口下(台17線)，經過雲嘉大橋，於園區迎賓涵洞之路口(台17線約114k處)右轉向西直行，即可到達園區「鰲鼓濕地生態展示館」。［開車前往］西濱快速道路(台61線)（北上）：往雲林於262K處之東石交流道出口下(台17線)，於台17線113.5~114k處，左轉經過台61線涵洞向西直行，即可到達園區服務中心「鰲鼓濕地生態展示館」。［大眾運輸］搭乘高鐵：至高鐵嘉義站下車，於一樓大廳2號出口，往1號公車月台搭乘嘉義客運『嘉義-朴子』線，於朴子站下車，接著轉搭『朴子-海埔地』路線，於『農場』站下車，可到達園區服務中心「鰲鼓濕地生態展示館」。嘉義客運參考網址為：http://wwm.cibus.com.tw/［大眾運輸］搭乘火車：至嘉義火車站下車於火車站前（中山路503號），搭乘嘉義客運『嘉義-朴子』線公車，於朴子站下車，接著轉搭『朴子-海埔地』路線，於『農場』站下車，可到達園區服務中心「鰲鼓濕地生態展示館」。［大眾運輸］幸福小黃(幸福東石2路)：1.採出發前2日辦理預約，台一大車隊預約電話：06-30000002.單趟起訖點，為嘉義縣東石鄉、布袋鎮或朴子市任一處，車資可折抵320元/趟，單趟車資不足420元，需付100元。3.相關資訊，可上網址：https://chiayiibus.cyhg.gov.tw/DynamicBusResult?routeId=65001",
      "ParkingInfo": "小型車：免收費，小型車停車格數 40。小型車：免收費，小型車停車格數 15。",
