      "TrafficInfo": "［開車前往］國道三號：霧峰系統交流道→國道六號埔里端左轉台14→霧社→右轉投83線→奧萬大。［開車前往］路線一：南下路線：國道一號南下彰化系統交流道(193K)→國道三號→霧峰系統交流道(214K)→國道六號埔里端→左轉台14→霧社→右轉投83線→奧萬大。［開車前往］路線二：北上路線：國道一號北上經東西向快速道路(例如台78、82、84)→國道三號→霧峰系統交流道(214K)→國道六號埔里端→左轉台14→霧社→右轉投83線→奧萬大。［大眾運輸］南投客運奧萬大賞楓專車：於賞楓旺季期間(10月至隔年3月底)之星期六日，由南投客運干城站發車採預約訂位(站牌與時刻表資訊:http://www.ntbus.com.tw/bs-tour.html)訂位專線049-2984031分機29 林小姐。台中干城站：台中市雙十路一段35-8號。高鐵台中站：高鐵站區一樓五號出口。［大眾運輸］南投客運DRTS：每日以九人座行駛固定班次，採預約訂位適合清境等周邊景點(站牌與時刻表資訊: http://www.ntbus.com.tw/bs-tour.html)，資訊請洽南投客運049-2984031分機29。搭乘火車(台中站)及高鐵(台中站)遊客，可搭乘「南投客運」往清境，或先搭乘往埔里再轉搭往清境至霧社下車後再站轉乘DRTS。",
