      "AttractionID": "Attraction_345040000G_030027",
      "AttractionName": "東眼山自然教育中心",
      "AlternateNames": [],
      "Description": "在雪山山脈尾稜的柳杉林裡，在真實的環境學習中，創造「人與人」、「人與環境」、「人與社會」之對話。  東眼山自然教育中心位於東眼山國家森林遊樂區內，屬石門水庫集水區範圍，為雪山山脈西稜之一部份，山形恰似人倒臥的側臉，清晨日出由側臉眼窩的位置升起，因而得名。森林組成兼具整齊優美的人工林及豐富多樣的天然林，還有三千萬年前蝦蟹留下的生痕化石，及其他海相沈積等地質景觀。",
