      "TrafficInfo": "［開車前往］路線說明：台東→11號省道→知本→樂山產業道路(東58線)→循知本溫泉指標即可到達。［大眾運輸］火車：省道台9線或台11線→知本→龍泉路(194縣道)→循知本國家森林遊樂區指標即可到達(位於道路終點)。［大眾運輸］搭乘客運：台東市或知本火車站搭乘東台灣客運8129車次至內溫泉站下車，往知本國家森林遊樂區方向步行約300公尺即可抵達（平日、假日：單程15班次（來回30班次））。東台灣客運查詢電話：089-328269。［大眾運輸］微笑單車-YouBike：知本火車站 (車站前) - 騎乘 40分鐘 (8.7 km) - 知本國家森林遊樂區 (停車場) 。",
