      "TrafficInfo": "［開車前往］路線說明：走北宜高速公路（國道五號）羅東出口，右轉接縣道196線，直行約5分鐘，過十字路口後穿過鐵路地下道，第一個紅綠燈右轉中正北路，直行約1分鐘即可抵達林業文化園區南停車場（林場肉羹斜對面），本停車場為收費停車場，停車費以小時計算。［大眾運輸］搭乘國道客運：首都客運『首都之星』：起訖點：台北市政府轉運站－羅東轉運站。於羅東站下車後，步行至萊爾富便利商店右轉直行至羅東火車站後站，穿越火車站至前站出口，直行至中正北路口右轉，沿中正北路直行約700公尺便可抵達羅東林業文化園區。步行時間約20分鐘。［大眾運輸］搭乘國道客運：葛瑪蘭客運：起訖點：板橋轉運站－台北轉運站－羅東轉運站。於羅東站下車後，步行至萊爾富便利商店右轉直行至羅東火車站後站，穿越火車站至前站出口，直行至中正北路口右轉，沿中正北路直行約700公尺便可抵達羅東林業文化園區。步行時間約20分鐘。［大眾運輸］搭乘國道客運：大都會客運『都會之星』：起訖點：捷運大坪林站－羅東轉運站。於羅東站下車後，步行至萊爾富便利商店右轉直行至羅東火車站後站，穿越火車站至前站出口，直行至中正北路口右轉，沿中正北路直行約700公尺便可抵達羅東林業文化園區。步行時間約20分鐘。［大眾運輸］搭乘國道客運：國光客運：起訖點：捷運圓山站－捷運南港展覽館站－羅東轉運站。於羅東站下車後，步行至萊爾富便利商店右轉直行至羅東火車站後站，穿越火車站至前站出口，直行至中正北路口右轉，沿中正北路直行約700公尺便可抵達羅東林業文化園區。步行時間約20分鐘。［大眾運輸］搭乘宜蘭縣內客運：國光客運：起訖點：頭城─南方澳線（路線編號：1766及1767），於「竹林站」下車後，轉林場路約步行3分鐘後即可抵達羅東林業文化園區。［大眾運輸］搭乘火車：羅東火車站前站出口，直行至中正北路口右轉，沿中正北路直行約700公尺便可抵達羅東林業文化園區。步行時間約10～15分鐘。詳情請至交通部台灣鐵路管理局網站查詢。",
